function Header() {
  return (
    <header className="site-header">
      <a className="brand" href="#top">
        <span className="logo" dangerouslySetInnerHTML={{ __html: DATA.logo }} />
        <span>{DATA.brand}</span>
      </a>
      <nav>
        <a href="#about">{DATA.ui.about}</a>
        <a href="#features">{DATA.features_title}</a>
        <a href="#faq">{DATA.ui.faq}</a>
        <a href="#contact">{DATA.ui.contact}</a>
      </nav>
    </header>
  );
}

function Hero() {
  return (
      <section className="hero hero-photo" style={{ "--hero-fg": DATA.photos.hero.text_color }}>
        <img className="hero-img" src={DATA.photos.hero.src} alt={DATA.photos.hero.alt} width={DATA.photos.hero.width} height={DATA.photos.hero.height} fetchpriority="high" />
        <div className="hero-text">
          <p className="eyebrow">{DATA.eyebrow}</p>
          <h1>{DATA.hero_heading}</h1>
          <p className="lead">{DATA.tagline}</p>
          <div className="btn-row">
            <a className="btn btn-primary" href="#contact">{DATA.cta_primary}</a>
            <a className="btn btn-ghost" href="#features">{DATA.cta_secondary}</a>
          </div>
        </div>
      </section>
  );
}

function About() {
  return (
    <section id="about" className={"section about" + (DATA.photos ? " about-photo-layout" : "")}>
      {DATA.photos && (
        <figure className="about-photo">
          <img src={DATA.photos.about.src} alt={DATA.photos.about.alt} width={DATA.photos.about.width} height={DATA.photos.about.height} loading="lazy" decoding="async" />
        </figure>
      )}
      <div className="about-text">
      <h2>{DATA.about_title}</h2>
      {DATA.about.map((p, i) => (
        <p key={i}>{p}</p>
      ))}
      {DATA.stats.length > 0 && <h3 className="stats-title">{DATA.stats_title}</h3>}
      {DATA.stats.length > 0 && (
        <ul className="stats">
          {DATA.stats.map((s) => (
            <li key={s.label}>
              <strong>{s.value}</strong>
              <span>{s.label}</span>
            </li>
          ))}
        </ul>
      )}
      </div>
    </section>
  );
}

function Gallery() {
  if (!DATA.photos || DATA.photos.tiles.length === 0) return null;
  return (
    <section id="gallery" className="section gallery">
      <h2>{DATA.ui.gallery}</h2>
      <div className="gallery-grid">
        {DATA.photos.tiles.map((t) => (
          <figure key={t.src}>
            <img src={t.src} alt={t.alt} width={t.width} height={t.height} loading="lazy" decoding="async" />
          </figure>
        ))}
      </div>
    </section>
  );
}

function Highlights() {
  return (
    <section className="section highlights" aria-label="Highlights">
      {DATA.highlights.map((h) => (
        <div className="hl" key={h.title}>
          <strong>{h.title}</strong>
          <span>{h.text}</span>
        </div>
      ))}
    </section>
  );
}

function Features() {
  return (
    <section id="features" className="section features cards">
      <h2>{DATA.features_title}</h2>
      <div className="grid">
        {DATA.features.map((f, i) => (
          <article className="card" key={f.title}>
            <span className="icon" dangerouslySetInnerHTML={{ __html: DATA.icons[i] }} />
            <h3>{f.title}</h3>
            <p>{f.text}</p>
          </article>
        ))}
      </div>
    </section>
  );
}

function Pricing() {
  if (!DATA.pricing) return null;
  return (
    <section id="pricing" className="section pricing">
      <h2>{DATA.ui.pricing}</h2>
      <div className="grid">
        {DATA.pricing.map((p) => (
          <article className="card" key={p.name}>
            <h3>{p.name}</h3>
            <p className="price">{p.price}</p>
          </article>
        ))}
      </div>
    </section>
  );
}

function Team() {
  if (!DATA.team) return null;
  return (
    <section id="team" className="section team">
      <h2>{DATA.ui.team}</h2>
      <div className="grid">
        {DATA.team.map((m) => (
          <article className="card" key={m.name}>
            <h3>{m.name}</h3>
            <p>{m.role}</p>
          </article>
        ))}
      </div>
    </section>
  );
}

function Testimonials() {
  if (!DATA.testimonials) return null;
  return (
    <section id="reviews" className="section reviews">
      <h2>{DATA.ui.testimonials}</h2>
      <div className="grid">
        {DATA.testimonials.map((t) => (
          <blockquote className="card" key={t.name}>
            <p>{t.text}</p>
            <cite>{t.name}</cite>
          </blockquote>
        ))}
      </div>
    </section>
  );
}

function Blog() {
  if (!DATA.blog) return null;
  return (
    <section id="journal" className="section blog">
      <h2>{DATA.blog_title}</h2>
      <div className="grid">
        {DATA.blog.map((b) => (
          <article className="card" key={b.title}>
            <h3>{b.title}</h3>
            <p>{b.excerpt}</p>
          </article>
        ))}
      </div>
    </section>
  );
}

function Steps() {
  return (
    <section id="steps" className="section steps">
      <h2>{DATA.steps_title}</h2>
      <ol>
        {DATA.steps.map((s, i) => (
          <li key={s.title}>
            <span className="num">{i + 1}</span>
            <h3>{s.title}</h3>
            <p>{s.text}</p>
          </li>
        ))}
      </ol>
    </section>
  );
}

function Faq() {
  return (
    <section id="faq" className="section faq">
      <h2>{DATA.faq_title}</h2>
      {DATA.faq.map((f) => (
        <details key={f.q}>
          <summary>{f.q}</summary>
          <p>{f.a}</p>
        </details>
      ))}
    </section>
  );
}

function CallToAction() {
  return (
    <section id="contact" className="section cta">
      <h2>{DATA.cta_title}</h2>
      <p>{DATA.cta_text}</p>
      <a className="btn btn-primary" href={DATA.contact.phone ? "tel:" + DATA.contact.phone : DATA.contact.email ? "mailto:" + DATA.contact.email : "#top"}>{DATA.cta_primary}</a>
      <ul className="contact">
        {DATA.contact.phone && <li>{DATA.ui.call}: {DATA.contact.phone}</li>}
        {DATA.contact.whatsapp && <li>WhatsApp: {DATA.contact.whatsapp}</li>}
        {DATA.contact.email && <li>{DATA.ui.email}: {DATA.contact.email}</li>}
        {DATA.contact.address && <li>{DATA.ui.address}: {DATA.contact.address}</li>}
        {DATA.contact.hours && <li>{DATA.ui.hours}: {DATA.contact.hours.join(" · ")}</li>}
        {DATA.contact.place && <li>{DATA.ui.based_in}: {DATA.contact.place}</li>}
      </ul>
    </section>
  );
}

function Footer() {
  return <footer className="site-footer">{DATA.footer}</footer>;
}

function App() {
  return (
    <div id="top">
      <Header />
      <main>
        <Hero />
        <Highlights />
        <About />
        <Features />
        <Gallery />
        <Pricing />
        <Steps />
        <Team />
        <Testimonials />
        <Blog />
        <Faq />
        <CallToAction />
      </main>
      <Footer />
    </div>
  );
}

ReactDOM.createRoot(document.getElementById("root")).render(<App />);
